class Solution:
    def minProcessingCost(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        have, price, cost = k, 1, 0
        for x in nums:
            while have < x:
                cost = (cost + price) % MOD
                have += k
                price += 1
            have -= x
        return cost

